const VOCAB=[{word:'Bom dia',context:'Saudação',note:'Início de uma conversa cordial.'},{word:'Obrigado',context:'Cortesia',note:'Agradecimento no cotidiano.'},{word:'Reunião',context:'Trabalho',note:'Encontro para conversar e decidir em equipe.'},{word:'Equipe',context:'Trabalho',note:'Pessoas que atuam juntas.'},{word:'Ajuda',context:'Cotidiano',note:'Pedido de apoio em uma situação.'},{word:'Atendimento',context:'Trabalho',note:'Acolhimento e orientação ao público.'},{word:'Inclusão',context:'Cultura',note:'Participação com acesso e respeito às diferenças.'},{word:'Prazer',context:'Saudação',note:'Expressão usada ao conhecer alguém.'}];
const ICONS:Record<string,string>={home:'M3 10.5 12 3l9 7.5V21h-6v-7H9v7H3z',book:'M4 5h7a3 3 0 0 1 3 3v13a3 3 0 0 0-3-3H4z M20 5h-5a3 3 0 0 0-3 3v13a3 3 0 0 1 3-3h5z',spark:'M12 2l2.8 6.2L21 11l-6.2 2.8L12 20l-2.8-6.2L3 11l6.2-2.8z',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M4 21v-2c0-4.5 16-4.5 16 0v2',users:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M2 21v-2c0-4 12-4 12 0v2 M16 4c5 0 5 8 0 8 M17 16c3 0 5 2 5 5',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10 M10 22h4',settings:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M5.6 5.6l2.1 2.1 M16.3 16.3l2.1 2.1 M18.4 5.6l-2.1 2.1 M7.7 16.3l-2.1 2.1 M12 16a4 4 0 1 0 0-8 4 4 0 0 0 0 8',arrow:'M5 12h14 m-6-6 6 6-6 6',back:'M15 18l-6-6 6-6',check:'M4 12l5 5L20 6',message:'M4 4h16v12H9l-5 4z',briefcase:'M3 8h18v13H3z M9 8V4h6v4 M3 13h18',chart:'M4 20V12h4v8z M10 20V4h4v16z M16 20v-9h4v9z',play:'M8 5l12 7-12 7z',search:'M11 18a7 7 0 1 0 0-14 7 7 0 0 0 0 14z M16 16l5 5',close:'M5 5l14 14 M19 5L5 19',headphones:'M3 13V11a9 9 0 0 1 18 0v2 M3 13h4v7H5a2 2 0 0 1-2-2z M21 13h-4v7h2a2 2 0 0 0 2-2z',bookmark:'M5 3h14v18l-7-5-7 5z',calendar:'M4 5h16v16H4z M8 3v5 M16 3v5 M4 10h16',file:'M6 2h9l5 5v15H6z M15 2v5h5 M9 12h8 M9 16h8',graduation:'M2 9l10-6 10 6-10 6z M6 12v6c4 3 8 3 12 0v-6',send:'M3 21L22 12 3 3l3 8 9 1-9 1z',shield:'M12 2l9 4v6c0 6-4 9-9 10-5-1-9-4-9-10V6z',volume:'M4 10h4l6-5v14l-6-5H4z M18 8c2 2 2 6 0 8',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7z M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z',help:'M10 9a3 3 0 1 1 4 3c-1.5 1-2 2-2 3 M12 19h.01 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',filter:'M4 7h16 M7 12h10 M10 17h4',plus:'M12 4v16 M4 12h16',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',download:'M12 3v13 M7 11l5 5 5-5 M4 19v3h16v-3',logout:'M9 3H4v18h5 M13 7l5 5-5 5 M8 12h10',heart:'M12 21L4 13c-6-7 4-14 8-6 4-8 14-1 8 6z'};
function Icon(p:{name:string;size?:number}){return <svg aria-hidden="true" width={p.size||22} height={p.size||22} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d={ICONS[p.name]||ICONS.spark}/></svg>}
function Brand(p:{small?:boolean}){return <span className={'brand '+(p.small?'brand-small':'')}><img src="assets/mascote.png" alt=""/><span><strong>Sinalis</strong><em>EDUCAÇÃO INCLUSIVA</em></span></span>}
function Progress(p:{value:number}){return <div className="progress-track" role="progressbar" aria-valuenow={p.value} aria-valuemin={0} aria-valuemax={100}><span style={{width:Math.max(0,Math.min(100,p.value))+'%'}}/></div>}
function Button(p:{children?:any;onClick?:()=>void;kind?:string;icon?:string;disabled?:boolean;className?:string}){return <button type="button" disabled={p.disabled} onClick={p.onClick} className={'btn '+(p.kind||'primary')+' '+(p.className||'')}>{p.icon&&<Icon name={p.icon} size={18}/>} {p.children}</button>}
function Tile(p:{key?:any;icon:string;title:string;description?:string;onClick:()=>void;tone?:string;end?:boolean}){return <button className="tile" onClick={p.onClick}><span className={'tile-icon '+(p.tone||'orange')}><Icon name={p.icon} size={24}/></span><span className="tile-label"><strong>{p.title}</strong>{p.description&&<small>{p.description}</small>}</span>{p.end&&<span className="tile-next"><Icon name="arrow" size={18}/></span>}</button>}
function Tabs(p:{options:string[];active:string;onClick:(x:string)=>void}){return <div className="segmented">{p.options.map(x=><button key={x} className={x===p.active?'active':''} onClick={()=>p.onClick(x)}>{x}</button>)}</div>}
const DEFAULT_POSTS:Post[]=[{id:1,author:'Marina Costa',role:'Participante',body:'Como tornar reuniões mais acessíveis? Compartilhem recursos e práticas que funcionam nas equipes de vocês.',likes:12,comments:['Usar a pauta antecipadamente faz bastante diferença!']},{id:2,author:'Pedro Santos',role:'Comunidade',body:'Uma dica: pergunte sempre a preferência de comunicação da pessoa, em vez de presumir o que ela precisa.',likes:9,comments:[]}];
const initial:AppState={page:'welcome',role:null,tab:'Todas',track:'basic',lesson:'basic-1',choice:null,feedback:false,completed:[],bookmarks:[],messages:['Olá! Seja bem-vindo(a) ao espaço de comunicação do Sinalis.'],posts:DEFAULT_POSTS,activities:[],title:'',instructions:'',group:'Comunicação inclusiva',answerType:'Texto',showModal:'',toast:'',query:'',filter:'Todas',fontLarge:false,highContrast:false,reducedMotion:false,subtitles:true,notificationsRead:false,commentsDraft:{},draftPost:'',draftMessage:'',supportMessage:'',supportSent:false,faq:-1,recentPages:[]};
const STORE='sinalis-demo-v3';
function load():AppState{try{const s=JSON.parse(localStorage.getItem(STORE)||'{}');return {...initial,...s,page:s.role?(s.role==='educador'?'teacher':'home'):'welcome',showModal:'',toast:'',query:'',feedback:false,choice:null,recentPages:[]};}catch{return {...initial};}}
class App extends React.Component<{},AppState>{
 state:AppState=load();
 private toastTimer:any=null;
 componentDidMount(){window.addEventListener('popstate',this.pop);this.applyPref()}
 componentWillUnmount(){window.removeEventListener('popstate',this.pop)}
 pop=()=>{const p=location.hash.replace('#','') as Page; if(p){this.setState({page:p})}}
 componentDidUpdate(_p:{},old:AppState){if(old!==this.state){const snapshot={...this.state,showModal:'',toast:'',query:'',draftPost:this.state.draftPost};try{localStorage.setItem(STORE,JSON.stringify(snapshot));}catch{}if(old.fontLarge!==this.state.fontLarge||old.highContrast!==this.state.highContrast||old.reducedMotion!==this.state.reducedMotion)this.applyPref()}}
 applyPref(){document.documentElement.classList.toggle('font-large',this.state.fontLarge);document.documentElement.classList.toggle('high-contrast',this.state.highContrast);document.documentElement.classList.toggle('reduce-motion',this.state.reducedMotion)}
 go=(page:Page)=>{window.history.pushState({},'',`#${page}`);this.setState(s=>({page,query:'',tab:'Todas',filter:'Todas',recentPages:[...s.recentPages.slice(-8),s.page],showModal:'',feedback:false,choice:null}));window.scrollTo(0,0)}
 back=()=>{const list=this.state.recentPages;const page=list[list.length-1]||'home';history.pushState({},'',`#${page}`);this.setState({page,recentPages:list.slice(0,-1),showModal:''});window.scrollTo(0,0)}
 flash=(message:string)=>{this.setState({toast:message});clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>this.setState({toast:''}),3200)}
 role=(role:Role)=>{this.setState({role,track:role==='ouvinte'?'basic':'work'});this.go(role==='educador'?'teacher':'home')}
 percent=(track:Track)=>Math.round(track.lessons.filter(x=>this.state.completed.includes(x.id)).length/track.lessons.length*100)
 totalPercent=()=>Math.round(TRACKS.flatMap(x=>x.lessons).filter(x=>this.state.completed.includes(x.id)).length/TRACKS.flatMap(x=>x.lessons).length*100)
 chosenTrack=()=>TRACKS.find(t=>t.id===this.state.track)||TRACKS[0]
 chosenLesson=()=>this.chosenTrack().lessons.find(l=>l.id===this.state.lesson)||this.chosenTrack().lessons[0]
 openTrack=(id:string)=>{this.setState({track:id});this.go('track')}
 openLesson=(id:string)=>{this.setState({lesson:id,choice:null,feedback:false});this.go('lesson')}
 finishQuiz=()=>{const l=this.chosenLesson();if(this.state.choice===null){this.flash('Escolha uma resposta antes de verificar.');return}this.setState(s=>({feedback:true,completed:s.choice===l.correct&&!s.completed.includes(l.id)?[...s.completed,l.id]:s.completed}));}
 nextLesson=()=>{const t=this.chosenTrack(),i=t.lessons.findIndex(x=>x.id===this.state.lesson);if(i<t.lessons.length-1)this.openLesson(t.lessons[i+1].id);else this.go('progress')}
 toggleBookmark=(key:string)=>{this.setState(s=>({bookmarks:s.bookmarks.includes(key)?s.bookmarks.filter(b=>b!==key):[...s.bookmarks,key]}));this.flash(this.state.bookmarks.includes(key)?'Removido dos favoritos':'Salvo nos favoritos')}
 navItems():{label:string;icon:string;page:Page}[]{return this.state.role==='educador'?[{label:'Visão geral',icon:'home',page:'teacher'},{label:'Turmas',icon:'users',page:'students'},{label:'Biblioteca',icon:'book',page:'library'},{label:'Comunidade',icon:'message',page:'teacherCommunity'},{label:'Perfil',icon:'user',page:'profile'}]:[{label:'Início',icon:'home',page:'home'},{label:'Trilhas',icon:'graduation',page:'tracks'},{label:'Prática',icon:'spark',page:'practice'},{label:this.state.role==='surdo'?'Comunicação':'Comunidade',icon:'message',page:this.state.role==='surdo'?'chat':'community'},{label:'Perfil',icon:'user',page:'profile'}]}
 header(title:string,subtitle?:string,back=false){return <div className="page-head"><div className="head-top">{back?<button className="icon-button" onClick={this.back} aria-label="Voltar"><Icon name="back"/></button>:<Brand small/>}<div className="head-actions"><button className="icon-button notice-icon" onClick={()=>this.go('notifications')} aria-label="Notificações"><Icon name="bell"/>{!this.state.notificationsRead&&<i/>}</button><button className="avatar" aria-label="Perfil" onClick={()=>this.go('profile')}><Icon name="user" size={19}/></button></div></div>{title&&<><h1>{title}</h1>{subtitle&&<p className="subtitle">{subtitle}</p>}</>}</div>}
 section(title:string,action?:string,onClick?:()=>void){return <div className="section-heading"><h2>{title}</h2>{action&&<button className="text-action" onClick={onClick}>{action} <Icon name="arrow" size={15}/></button>}</div>}
 image(src:string,label:string,className='photo'){return <img className={className} src={src} alt={label}/>}
 welcome(){return <div className="welcome"><div className="welcome-top"><Brand/><span className="demo-tag">DEMONSTRAÇÃO INTERATIVA</span><h1>Comunicação<br/><span>que aproxima.</span></h1><p>Uma experiência de aprendizagem de Libras e inclusão para pessoas, equipes e educadores.</p></div><div className="welcome-visual"><div className="shape-one"/><div className="shape-two"/>{this.image('assets/people.webp','Duas pessoas sorrindo em um ambiente de trabalho','welcome-people')}</div><div className="welcome-actions"><Button onClick={()=>this.go('choose')}>Explorar a demonstração <Icon name="arrow" size={19}/></Button><p>Sem conta, senha ou cadastro.</p></div></div>}
 choose(){return <div className="choose-page"><button className="back-link" onClick={this.back}><Icon name="back" size={18}/> Voltar</button><div className="deco deco-top"/><h1>Como você<br/><span>vai aprender?</span></h1><p className="subtitle">Escolha uma experiência para explorar. Você pode trocar de perfil quando quiser.</p><div className="role-list"><button className="role-card" onClick={()=>this.role('surdo')}><span className="role-icon teal"><Icon name="user" size={31}/></span><span><strong>Pessoa surda</strong><small>Aprendizagem, carreira e comunicação acessível</small></span><Icon name="arrow" size={20}/></button><button className="role-card" onClick={()=>this.role('ouvinte')}><span className="role-icon orange"><Icon name="users" size={31}/></span><span><strong>Pessoa ouvinte</strong><small>Aprenda Libras e pratique a inclusão</small></span><Icon name="arrow" size={20}/></button><button className="role-card" onClick={()=>this.role('educador')}><span className="role-icon wine"><Icon name="graduation" size={31}/></span><span><strong>Educador(a)</strong><small>Turmas, atividades e materiais pedagógicos</small></span><Icon name="arrow" size={20}/></button></div><div className="hint-card"><Icon name="spark"/><span>É uma demo: tudo acontece no seu navegador, sem dados reais ou autenticação.</span></div></div>}
 home(){const surdo=this.state.role==='surdo';return <>{this.header('Olá, visitante!','Seu desenvolvimento continua aqui.') }<section className="hero-card"><div className="hero-content"><span className="eyebrow">CONTINUE APRENDENDO</span><h2>{surdo?'Libras no trabalho':'Primeiras conversas'}</h2><Progress value={this.percent(TRACKS.find(t=>t.id===(surdo?'work':'basic'))! )}/><span className="hero-caption">{this.percent(TRACKS.find(t=>t.id===(surdo?'work':'basic'))!)}% concluído</span><Button kind="white" onClick={()=>this.openTrack(surdo?'work':'basic')}>Continuar <Icon name="arrow" size={17}/></Button></div>{this.image('assets/libras.webp','Pessoa demonstrando comunicação por sinais','hero-photo')}</section><div className="quick-grid">{(surdo?[['book','Minhas trilhas','tracks'],['play','Aulas','track'],['users','Comunidade','community'],['briefcase','Carreira','career']]:[['book','Aprenda Libras','learn'],['users','Apoie a inclusão','inclusion'],['message','Comunique-se','chat'],['users','Comunidade','community']]).map(([ico,label,page])=><Tile key={label} icon={ico} title={label} onClick={()=>page==='track'?this.openTrack(surdo?'work':'basic'):this.go(page as Page)}/>)}</div>{this.section('Para sua jornada','Ver trilhas',()=>this.go('tracks'))}<div className="featured-list">{TRACKS.filter(t=>surdo?t.id!=='basic':t.id!=='career').slice(0,2).map(t=>this.trackMini(t))}</div><div className="soft-banner"><span className="banner-icon"><Icon name="briefcase" size={29}/></span><div><strong>Capacitação da empresa</strong><p>Conteúdos acessíveis para desenvolver equipes.</p></div><button onClick={()=>this.go('training')} aria-label="Explorar capacitação"><Icon name="arrow"/></button></div></>}
 trackMini(t:Track){return <button key={t.id} className="track-mini" onClick={()=>this.openTrack(t.id)}>{this.image(t.image,'', 'track-mini-image')}<span><strong>{t.title}</strong><small>{t.lessons.length} aulas • {t.subtitle}</small><Progress value={this.percent(t)}/></span><Icon name="arrow" size={20}/></button>}
 tracks(){const filtered=TRACKS.filter(t=>this.state.filter==='Todas'||(this.state.filter==='Em andamento'&&this.percent(t)>0&&this.percent(t)<100)||(this.state.filter==='Concluídas'&&this.percent(t)===100));return <>{this.header('Sua formação','Desenvolva novas habilidades no seu ritmo.',true)}<Tabs options={['Todas','Em andamento','Concluídas']} active={this.state.filter} onClick={filter=>this.setState({filter})}/><div className="stack spaced">{filtered.length?filtered.map(t=>this.trackMini(t)):<div className="empty-state"><Icon name="book" size={34}/><h3>Nenhuma trilha por aqui</h3><p>Continue explorando suas aulas e volte para acompanhar o progresso.</p><Button kind="outline" onClick={()=>this.setState({filter:'Todas'})}>Ver todas</Button></div>}</div><div className="soft-banner"><Icon name="chart" size={24}/><span>Seu avanço acompanha você nesta demonstração.</span><button onClick={()=>this.go('progress')}>Ver progresso</button></div></>}
 track(){const t=this.chosenTrack(),done=this.percent(t);return <>{this.header(t.title,t.subtitle,true)}<div className="media-banner">{this.image(t.image,'Fotografia ilustrativa da trilha')}<span className="media-badge"><Icon name="graduation" size={16}/> {t.lessons.length} aulas</span></div><div className="card course-summary"><div><strong>Seu progresso</strong><b>{done}%</b></div><Progress value={done}/><p>Aprenda com exemplos, explore os conceitos e resolva exercícios interativos.</p></div>{this.section('Módulos e aulas')}<div className="stack">{t.lessons.map((l,i)=><button key={l.id} className="lesson-row" onClick={()=>this.openLesson(l.id)}><span className={'lesson-index '+(this.state.completed.includes(l.id)?'finished':'')}>{this.state.completed.includes(l.id)?<Icon name="check" size={18}/>:String(i+1).padStart(2,'0')}</span><span><strong>{l.title}</strong><small>{l.description}</small><span className="row-meta"><Icon name="clock" size={14}/> {l.minutes} min {this.state.completed.includes(l.id)?' · Concluída':' · Disponível'}</span></span><Icon name="arrow" size={19}/></button>)}</div><Button onClick={()=>this.openLesson(t.lessons.find(l=>!this.state.completed.includes(l.id))?.id||t.lessons[0].id)}>{done===100?'Revisar trilha':'Começar a aprender'}</Button></>}
 lesson(){const l=this.chosenLesson(),t=this.chosenTrack(),index=t.lessons.findIndex(x=>x.id===l.id)+1;return <>{this.header(l.title,`${t.title} · Aula ${index} de ${t.lessons.length}`,true)}<div className="media-banner media-lesson">{this.image(t.image,`Ilustração para ${l.title}`)}<span className="media-stamp"><Icon name="book" size={16}/> Prévia ilustrativa</span></div><div className="notice"><Icon name="eye"/><span>A demo apresenta conteúdo introdutório. O vídeo em Libras definitivo será incluído na versão de produção.</span></div><div className="lesson-body"><span className="eyebrow orange-text">AULA {index.toString().padStart(2,'0')}</span><h2>Vamos aprender?</h2><p>{l.description}</p><div className="lesson-tip"><Icon name="spark" size={23}/><div><strong>Para lembrar</strong><p>{l.takeaway}</p></div></div><button className="inline-toggle" onClick={()=>this.setState(s=>({subtitles:!s.subtitles}))}><Icon name="file" size={19}/>{this.state.subtitles?'Ocultar transcrição de apoio':'Mostrar transcrição de apoio'}<span>{this.state.subtitles?'Ativa':'Inativa'}</span></button>{this.state.subtitles&&<p className="transcript">{l.description} {l.takeaway}</p>}</div><Button onClick={()=>this.go('practice')}>Fazer atividade prática <Icon name="arrow" size={18}/></Button></>}
 practice(){const l=this.chosenLesson(),has=this.state.choice!==null,ok=this.state.choice===l.correct;return <>{this.header('Hora de praticar',`${this.chosenTrack().title} · Atividade de fixação`,true)}<div className="practice-counter"><span>Atividade prática</span><strong>01 / 01</strong></div><Progress value={this.state.feedback?100:45}/><div className="quiz-media"><div className="quiz-orb"><Icon name="spark" size={42}/></div><p>Reflita sobre uma situação do dia a dia.</p></div><h2 className="question">{l.question}</h2><div className="answers">{l.answers.map((x,i)=><button disabled={this.state.feedback} key={i} className={'answer '+(this.state.choice===i?'selected ':'')+(this.state.feedback&&i===l.correct?'correct ':'')+(this.state.feedback&&i===this.state.choice&&!ok?'incorrect':'')} onClick={()=>this.setState({choice:i})}><span className="radio">{this.state.choice===i&&<i/>}</span>{x}</button>)}</div>{this.state.feedback&&<div className={'feedback '+(ok?'success':'warning')}><Icon name={ok?'check':'help'}/><span><strong>{ok?'Muito bem! Aula concluída.':'Quase lá! Tente novamente.'}</strong><small>{l.takeaway}</small></span></div>}<Button disabled={!has} onClick={()=>{if(!this.state.feedback)this.finishQuiz();else if(ok)this.nextLesson();else this.setState({choice:null,feedback:false})}}>{!this.state.feedback?'Verificar resposta':ok?'Próxima etapa':'Tentar de novo'}</Button></>}
 vocabulary(){const results=VOCAB.filter(v=>(v.word+v.context).toLowerCase().includes(this.state.query.toLowerCase()));return <>{this.header('Vocabulário profissional','Explore expressões e seus contextos de uso.',true)}<div className="search"><Icon name="search"/><input placeholder="Buscar uma palavra" value={this.state.query} onChange={e=>this.setState({query:e.target.value})}/></div><Tabs options={['Todas','Trabalho','Saudação','Cotidiano']} active={this.state.filter} onClick={filter=>this.setState({filter})}/><div className="stack">{results.filter(x=>this.state.filter==='Todas'||x.context===this.state.filter).map(x=><div className="word-card" key={x.word}><div className="word-icon"><Icon name="message"/></div><span><strong>{x.word}</strong><small>{x.context} · {x.note}</small></span><button className={'icon-button '+(this.state.bookmarks.includes(x.word)?'is-saved':'')} aria-label="Salvar expressão" onClick={()=>this.toggleBookmark(x.word)}><Icon name="bookmark"/></button></div>)}{results.length===0&&<p className="muted">Nenhuma palavra encontrada.</p>}</div><div className="notice"><Icon name="help"/><span>Esta demonstração apresenta significados em português. Vídeos de sinais validados por especialistas serão adicionados ao produto.</span></div></>}
 progressPage(){const completed=this.state.completed.length;return <>{this.header('Seu desenvolvimento','Acompanhe sua evolução na formação.',true)}<div className="progress-hero"><span>PROGRESSO DA JORNADA</span><div><strong>{this.totalPercent()}%</strong><span>da jornada concluída</span></div><Progress value={this.totalPercent()}/></div><div className="metrics"><div className="metric"><Icon name="book"/><strong>{completed}</strong><small>aulas concluídas</small></div><div className="metric"><Icon name="clock"/><strong>{completed*7} min</strong><small>de estudo</small></div></div>{this.section('Competências desenvolvidas')}<div className="card progress-list">{TRACKS.map(t=><div className="skill-row" key={t.id}><span>{t.title}</span><strong>{this.percent(t)}%</strong><Progress value={this.percent(t)}/></div>)}</div><div className="soft-banner"><Icon name="file"/><div><strong>Certificado da trilha</strong><p>{TRACKS.some(t=>this.percent(t)===100)?'Você concluiu uma trilha!':'Conclua todas as aulas de uma trilha para liberar a conquista de demonstração.'}</p></div></div><Button onClick={()=>this.go('tracks')}>Continuar meus estudos</Button></>}
 chat(){return <>{this.header('Comunicação','Escolha a maneira mais confortável de conversar.',true)}<div className="card chat-card"><h3>Como deseja se comunicar?</h3><Tabs options={['Texto','Libras','Áudio']} active={this.state.tab==='Todas'?'Texto':this.state.tab} onClick={tab=>{this.setState({tab});if(tab!=='Texto')this.flash(`${tab}: função ilustrativa. O chat de texto está disponível na demo.`)}}/><div className="conversation"><div className="bubble received">Olá! Como podemos melhorar a comunicação na equipe?</div>{this.state.messages.map((m,i)=><div key={i} className={'bubble '+(i===0?'received':'sent')}>{m}</div>)}</div><div className="message-compose"><input value={this.state.draftMessage} placeholder="Escreva sua mensagem" onChange={e=>this.setState({draftMessage:e.target.value})} onKeyDown={e=>{if(e.key==='Enter')this.sendMessage()}}/><button aria-label="Enviar mensagem" onClick={this.sendMessage}><Icon name="send" size={20}/></button></div></div><div className="notice"><Icon name="shield" size={20}/><span>Conversa demonstrativa salva somente neste navegador. Não existem outros participantes conectados.</span></div></>}
 sendMessage=()=>{if(!this.state.draftMessage.trim())return;this.setState(s=>({messages:[...s.messages,s.draftMessage.trim()],draftMessage:''}));}
 career(){return <>{this.header('Trabalho e carreira','Desenvolva sua jornada profissional.',true)}<div className="career-feature"><div><h2>Preparar-se para o mercado</h2><p>Dicas e conteúdos para conquistar novas oportunidades.</p></div>{this.image('assets/career.webp','Pessoa em ambiente profissional')}</div><div className="stack"><Tile icon="file" title="Currículo acessível" description="Organize suas experiências profissionais." onClick={()=>this.openTrack('career')} end/><Tile icon="users" title="Entrevistas de emprego" description="Dicas de preparação e comunicação." onClick={()=>this.openTrack('career')} end/><Tile icon="chart" title="Comunicação profissional" description="Colaboração no ambiente de trabalho." onClick={()=>this.openTrack('work')} end/></div>{this.section('Em destaque')}<div className="soft-banner"><Icon name="heart" size={24}/><div><strong>Inclusão no ambiente de trabalho</strong><p>Práticas acessíveis para equipes e lideranças.</p></div><button onClick={()=>this.go('inclusion')} aria-label="Conhecer boas práticas"><Icon name="arrow"/></button></div></>}
 training(){return <>{this.header('Qualificação profissional','Formação para o seu próximo passo.',true)}{this.section('Trilhas recomendadas')}<div className="stack">{[TRACKS[2],TRACKS[3],TRACKS[0]].map(t=>this.trackMini(t))}</div><div className="media-banner">{this.image('assets/libras.webp','Pessoa comunicando por sinais')}<span className="media-stamp">Conteúdos com apoio de Libras</span></div><Button onClick={()=>this.go('tracks')}>Ver todas as trilhas</Button></>}
 reading(){return <>{this.header('Leitura e cultura','Aprenda com histórias e informação.',true)}<Tabs options={['Todas','Histórias','Notícias']} active={this.state.filter} onClick={filter=>this.setState({filter})}/><article className="reading-feature">{this.image('assets/reading.webp','Pessoas lendo e compartilhando histórias')}<div><h2>Histórias que conectam</h2><p>Leitura acessível e comunicação para todas as pessoas.</p><Button onClick={()=>this.go('article')}>Começar leitura</Button></div></article><div className="stack"><Tile icon="file" title="Notícias em linguagem simples" description="Leituras curtas sobre inclusão e cultura." onClick={()=>this.go('article')} end/><Tile icon="calendar" title="Agenda cultural acessível" description="Boas práticas para eventos inclusivos." onClick={()=>this.go('inclusion')} end/></div></>}
 article(){return <>{this.header('Histórias que conectam','Leitura • 3 minutos',true)}<div className="media-banner">{this.image('assets/reading.webp','Pessoas compartilhando a leitura')}</div><div className="article-content"><h2>Uma conversa muda um ambiente</h2><p>Na equipe de uma pequena empresa, as pessoas começaram a perceber que todos se comunicavam de maneiras diferentes. Para melhorar as reuniões, decidiram compartilhar a pauta com antecedência, usar recursos visuais e garantir que cada participante tivesse espaço para contribuir.</p><p>A experiência mostrou que a inclusão acontece em atitudes cotidianas: perguntar, escutar, aprender e adaptar a comunicação.</p><blockquote>“Comunicar bem é garantir que todas as pessoas possam participar.”</blockquote><p>O Sinalis reúne trilhas e atividades para ajudar pessoas e organizações a construir essas práticas.</p></div><Button kind="outline" icon="bookmark" onClick={()=>this.toggleBookmark('Histórias que conectam')}>{this.state.bookmarks.includes('Histórias que conectam')?'Remover dos salvos':'Salvar para ler depois'}</Button><Button onClick={()=>this.go('tracks')}>Explorar aprendizagem</Button></>}
 learn(){return <>{this.header('Aprenda Libras','Sinais e expressões para o dia a dia.',true)}<div className="media-banner">{this.image('assets/libras.webp','Pessoa usando comunicação por sinais')}<span className="media-stamp">Módulos para iniciantes</span></div><h2 className="section-title">Primeiras conversas</h2><p className="muted">Comece por conceitos básicos e avance para situações do trabalho.</p><Button onClick={()=>this.openTrack('basic')}>Começar módulo</Button><div className="stack spaced"><Tile icon="users" title="Apresentações" description="Conhecendo a Libras" onClick={()=>{this.setState({track:'basic'});this.openLesson('basic-1')}} end/><Tile icon="message" title="Cumprimentos" description="Expressões em contexto" onClick={()=>{this.setState({track:'basic'});this.openLesson('basic-2')}} end/><Tile icon="briefcase" title="Expressões no trabalho" description="Comunicação inclusiva" onClick={()=>this.openTrack('work')} end/></div></>}
 inclusion(){return <>{this.header('Apoie a inclusão','Boas práticas que fazem diferença.',true)}<div className="inclusion-banner"><h2>Torne sua <span>comunicação</span> acessível.</h2><div className="circle-orange"/><div className="circle-teal"/></div><div className="stack spaced"><Tile icon="message" title="Pergunte a preferência de comunicação" description="Respeite como cada pessoa se comunica." onClick={()=>this.openTrack('service')} end/><Tile icon="eye" title="Use recursos visuais e legendas" description="Facilite o acesso às informações." onClick={()=>this.go('settings')} end/><Tile icon="users" title="Garanta participação nas reuniões" description="Inclua todas as pessoas nas discussões e decisões." onClick={()=>this.openTrack('work')} end/><Tile icon="file" title="Guia para equipes" description="Práticas e recomendações para o trabalho." onClick={()=>this.go('article')} end/></div><Button onClick={()=>this.go('tracks')}>Explorar boas práticas</Button></>}
 community(teacher=false){const posts=this.state.posts;return <>{this.header(teacher?'Comunidade docente':'Comunidade',teacher?'Compartilhe práticas e experiências.':'Trocas, encontros e conexões.',true)}<div className="card compose-card"><strong>Compartilhe uma ideia</strong><textarea placeholder="Qual prática inclusiva você gostaria de compartilhar?" rows={3} value={this.state.draftPost} onChange={e=>this.setState({draftPost:e.target.value})}/><div><small>Publicação local da demo</small><Button kind="small" onClick={()=>{if(!this.state.draftPost.trim()){this.flash('Escreva sua mensagem.');return}this.setState(s=>({posts:[{id:Date.now(),author:'Você',role:teacher?'Educador(a)':'Participante',body:s.draftPost.trim(),likes:0,comments:[]},...s.posts],draftPost:''}));this.flash('Publicação criada nesta demonstração.')}} icon="plus">Publicar</Button></div></div><div className="stack spaced">{posts.map(p=><article key={p.id} className="post"><div className="post-head"><span className="post-avatar"><Icon name="user"/></span><div><strong>{p.author}</strong><small>{p.role} · Demonstração</small></div></div><p>{p.body}</p><div className="post-actions"><button className={p.liked?'liked':''} onClick={()=>this.setState(s=>({posts:s.posts.map(x=>x.id===p.id?{...x,liked:!x.liked,likes:x.likes+(x.liked?-1:1)}:x)}))}><Icon name="heart" size={18}/> {p.likes} curtidas</button><button onClick={()=>this.setState({showModal:'comment:'+p.id})}><Icon name="message" size={18}/> Responder ({p.comments.length})</button></div>{p.comments.length>0&&<div className="post-comments">{p.comments.map((c,i)=><div key={i}><Icon name="message" size={16}/>{c}</div>)}</div>}</article>)}</div><div className="soft-banner"><Icon name="calendar"/><span>Participe da nossa roda de conversa demonstrativa sobre inclusão.</span></div></>}
 teacher(){return <>{this.header('Olá, educador(a)!','Acompanhe suas turmas e formações.') }<div className="teacher-hero"><h2>Ensinar é abrir caminhos.</h2><p>Crie atividades acessíveis e acompanhe sua comunidade de aprendizagem.</p><img src="assets/mascote.png" alt="Mascote Sinalis"/></div><div className="metrics"><button className="metric" onClick={()=>this.go('students')}><Icon name="users"/><strong>3</strong><small>turmas ilustrativas</small></button><button className="metric" onClick={()=>this.go('students')}><Icon name="chart"/><strong>48</strong><small>participantes fictícios</small></button></div>{this.section('Minhas turmas','Ver todas',()=>this.go('students'))}<div className="stack"><Tile icon="graduation" title="Comunicação inclusiva" description="28 participantes • 72% da turma" onClick={()=>this.go('students')} end/><Tile icon="graduation" title="Libras no trabalho" description="20 participantes • 61% da turma" onClick={()=>this.go('students')} end/></div><Button onClick={()=>this.go('activity')} icon="plus">Criar atividade</Button>{this.section('Atalhos para educadores')}<div className="quick-grid"><Tile icon="users" title="Alunos" onClick={()=>this.go('students')}/><Tile icon="book" title="Biblioteca" onClick={()=>this.go('library')}/><Tile icon="message" title="Comunidade" onClick={()=>this.go('teacherCommunity')}/><Tile icon="file" title="Atividades" onClick={()=>this.go('activity')}/></div></>}
 activity(){return <>{this.header('Criar atividade','Prepare um conteúdo acessível.',true)}<div className="card form-card"><label>Título da atividade<input value={this.state.title} maxLength={90} placeholder="Ex.: Apresentação profissional" onChange={e=>this.setState({title:e.target.value})}/></label><label>Turma<select value={this.state.group} onChange={e=>this.setState({group:e.target.value})}><option>Comunicação inclusiva</option><option>Libras no trabalho</option><option>Atendimento inclusivo</option></select></label><label>Instruções<textarea rows={4} value={this.state.instructions} placeholder="Explique o que o participante deverá fazer..." onChange={e=>this.setState({instructions:e.target.value})}/></label><div className="form-label">Formato de resposta</div><Tabs options={['Texto','Vídeo','Áudio']} active={this.state.answerType} onClick={answerType=>this.setState({answerType})}/><div className="notice"><Icon name="eye"/><span>Formatos de vídeo e áudio aparecem como opções, mas o upload não está conectado nesta demo.</span></div><Button kind="outline" onClick={()=>this.saveActivity(false)}>Salvar rascunho</Button><Button onClick={()=>this.saveActivity(true)}>Publicar atividade na demo</Button></div>{this.state.activities.length>0&&<>{this.section('Atividades criadas')}<div className="stack">{this.state.activities.map((a,i)=><Tile key={i} icon="file" title={a.title} description={`${a.group} · ${a.published?'Publicada':'Rascunho'} · ${a.answerType}`} onClick={()=>this.setState({showModal:'activity:'+i})} end/>)}</div></>}</>}
 saveActivity=(published:boolean)=>{const {title,instructions,group,answerType}=this.state;if(!title.trim()||!instructions.trim()){this.flash('Preencha o título e as instruções.');return}this.setState(s=>({activities:[{title:title.trim(),instructions:instructions.trim(),group,answerType,published,created:Date.now()},...s.activities],title:'',instructions:''}));this.flash(published?'Atividade publicada na demonstração.':'Rascunho salvo localmente.')}
 students(){return <>{this.header('Acompanhar alunos','Turma: Comunicação inclusiva',true)}<div className="metrics"><div className="metric"><Icon name="users"/><strong>28</strong><small>participantes fictícios</small></div><div className="metric"><Icon name="chart"/><strong>72%</strong><small>conclusão ilustrativa</small></div></div><div className="notice"><Icon name="help"/><span>Os nomes e indicadores abaixo são dados fictícios para demonstração. Novas atividades criadas são armazenadas apenas neste dispositivo.</span></div>{this.section('Participantes')}<div className="stack">{[['Ana Souza',80],['Rafael Lima',60],['Marina Costa',75],['João Alves',54]].map(([n,v])=><button key={n} className="student-row" onClick={()=>this.setState({showModal:'student:'+n})}><span className="post-avatar"><Icon name="user"/></span><span><strong>{n}</strong><Progress value={v as number}/></span><b>{v}%</b><Icon name="arrow" size={17}/></button>)}</div>{this.section('Atividades da turma')}<div className="stack">{this.state.activities.length?this.state.activities.map((a,i)=><Tile key={i} icon="file" title={a.title} description={a.group} onClick={()=>this.setState({showModal:'activity:'+i})} end/>):<p className="muted">Nenhuma atividade criada ainda. Experimente publicar uma atividade.</p>}</div><Button onClick={()=>this.go('activity')}>Criar nova atividade</Button></>}
 library(){const materials=[{title:'Plano de aula: apresentações',type:'Planos',desc:'Atividade sobre apresentações no trabalho.'},{title:'Comunicação inclusiva em equipe',type:'Vídeos',desc:'Orientações sobre comunicação acessível.'},{title:'Guia de atividades acessíveis',type:'Guias',desc:'Sugestões de formatos e adaptações.'},{title:'Checklist de reunião inclusiva',type:'Guias',desc:'Materiais de apoio para profissionais.'}];return <>{this.header('Biblioteca pedagógica','Recursos para formações inclusivas.',true)}<div className="search"><Icon name="search"/><input placeholder="Buscar material" value={this.state.query} onChange={e=>this.setState({query:e.target.value})}/></div><Tabs options={['Todas','Planos','Vídeos','Guias']} active={this.state.filter} onClick={filter=>this.setState({filter})}/><div className="stack spaced">{materials.filter(x=>(this.state.filter==='Todas'||x.type===this.state.filter)&&x.title.toLowerCase().includes(this.state.query.toLowerCase())).map(x=><div className="resource" key={x.title}><span className="resource-icon"><Icon name="file" size={25}/></span><div><strong>{x.title}</strong><small>{x.desc}</small><span>{x.type} · Material de exemplo</span></div><button className="icon-button" aria-label={`Salvar ${x.title}`} onClick={()=>this.toggleBookmark(x.title)}><Icon name={this.state.bookmarks.includes(x.title)?'check':'bookmark'}/></button></div>)}</div><div className="notice"><Icon name="file"/><span>Esta biblioteca contém títulos ilustrativos. Downloads de materiais completos estarão disponíveis futuramente.</span></div></>}
 profile(){return <>{this.header('Meu perfil','Sua experiência demonstrativa.',true)}<div className="profile-card"><div className="profile-avatar"><Icon name="user" size={33}/></div><div><h2>Visitante Sinalis</h2><p>{this.state.role==='educador'?'Educador(a)':this.state.role==='surdo'?'Pessoa surda':'Pessoa ouvinte'} · Modo demonstração</p></div></div><div className="stack"><Tile icon="users" title="Trocar de perfil" description="Experimente outra jornada sem cadastro." onClick={()=>this.go('choose')} end/><Tile icon="chart" title="Meu progresso" description={`${this.state.completed.length} aulas concluídas`} onClick={()=>this.go('progress')} end/><Tile icon="bookmark" title="Meus favoritos" description={`${this.state.bookmarks.length} conteúdos salvos`} onClick={()=>this.setState({showModal:'favorites'})} end/><Tile icon="bell" title="Notificações" onClick={()=>this.go('notifications')} end/><Tile icon="settings" title="Preferências de acessibilidade" onClick={()=>this.go('settings')} end/><Tile icon="headphones" title="Ajuda e suporte" onClick={()=>this.go('support')} end/><Tile icon="shield" title="Privacidade da demo" onClick={()=>this.go('privacy')} end/></div><Button kind="outline" icon="logout" onClick={()=>this.setState({showModal:'restart'})}>Reiniciar a demonstração</Button></>}
 settings(){return <>{this.header('Configurações','Personalize sua experiência acessível.',true)}<div className="card settings-card"><h3>Acessibilidade</h3>{[['subtitles','Legendas de apoio','Exibir transcrição nas aulas'],['fontLarge','Texto ampliado','Aumentar o tamanho das fontes'],['highContrast','Alto contraste','Intensificar contraste de cores'],['reducedMotion','Reduzir movimento','Evitar animações não essenciais']].map(([key,title,desc])=><label className="toggle-row" key={key}><span><strong>{title}</strong><small>{desc}</small></span><input type="checkbox" checked={!!(this.state as any)[key]} onChange={e=>this.setState({[key]:e.target.checked} as any)}/><i/></label>)}</div>{this.section('Conta e suporte')}<div className="stack"><Tile icon="bell" title="Notificações" onClick={()=>this.go('notifications')} end/><Tile icon="help" title="Ajuda e suporte" onClick={()=>this.go('support')} end/><Tile icon="shield" title="Termos e privacidade" onClick={()=>this.go('privacy')} end/></div><Button kind="outline" onClick={()=>this.flash('Suas preferências foram salvas neste navegador.')}>Salvar preferências</Button></>}
 notifications(){return <>{this.header('Notificações','Novidades da sua jornada.',true)}<Tabs options={['Todas','Não lidas']} active={this.state.filter} onClick={filter=>this.setState({filter})}/>{this.state.notificationsRead&&this.state.filter==='Não lidas'?<div className="empty-state"><Icon name="bell" size={34}/><p>Você está em dia. Nenhuma notificação pendente.</p></div>:<div className="stack spaced"><Tile icon="file" title="Nova atividade disponível" description="Comece a próxima aula de comunicação inclusiva." onClick={()=>this.openTrack('work')} end/><Tile icon="book" title="Seu material foi atualizado" description="Conheça recursos de aprendizagem." onClick={()=>this.go('library')} end/><Tile icon="users" title="Encontro da comunidade" description="Confira as conversas da comunidade." onClick={()=>this.go('community')} end/></div>}<Button kind="outline" onClick={()=>{this.setState({notificationsRead:true});this.flash('Todas marcadas como lidas.')}}>Marcar todas como lidas</Button></>}
 support(){const faqs=[['Como começar uma trilha?','Escolha Trilhas, abra um módulo e selecione uma aula. Faça a atividade para registrar a conclusão.'],['Como ativar as legendas?','Acesse Perfil > Configurações e ative Legendas de apoio.'],['Preciso criar uma conta?','Não. Esta demonstração não usa cadastro, senha nem dados pessoais.'],['Meu progresso fica salvo?','Sim, no armazenamento local deste navegador, até que você limpe os dados ou reinicie a demo.']];return <>{this.header('Como podemos ajudar?','Encontre orientações sobre a demonstração.',true)}{this.section('Dúvidas frequentes')}<div className="stack">{faqs.map(([q,a],i)=><div className="faq" key={q}><button onClick={()=>this.setState({faq:this.state.faq===i?-1:i})}>{q}<Icon name={this.state.faq===i?'close':'plus'} size={18}/></button>{this.state.faq===i&&<p>{a}</p>}</div>)}</div>{this.section('Enviar uma sugestão')}<div className="card form-card"><p className="muted">Conte o que melhoraria esta experiência.</p><textarea rows={4} placeholder="Escreva sua sugestão" value={this.state.supportMessage} onChange={e=>this.setState({supportMessage:e.target.value})}/><Button onClick={()=>{if(!this.state.supportMessage.trim())return this.flash('Escreva sua sugestão primeiro.');this.setState({supportSent:true,supportMessage:''});this.flash('Sugestão registrada localmente nesta demo.')}}>Registrar sugestão</Button>{this.state.supportSent&&<p className="success-note">Obrigado! Sua sugestão foi registrada localmente (não foi enviada a servidores).</p>}</div></>}
 privacy(){return <>{this.header('Privacidade da demonstração','Informações claras sobre esta experiência.',true)}<div className="card privacy-card"><Icon name="shield" size={36}/><h2>Você controla esta demonstração.</h2><p>O Sinalis V2 apresentado aqui é um protótipo funcional sem autenticação ou backend. Suas escolhas de perfil, progresso, mensagens e atividades são armazenadas somente no navegador usando localStorage.</p><p>Não são enviadas mensagens, cadastros, arquivos ou solicitações a servidores. Os participantes e indicadores de turma são ilustrativos.</p><p>O conteúdo educacional é demonstrativo e vídeos de Libras precisam de revisão e produção especializada antes de utilização pedagógica real.</p></div><Button kind="outline" onClick={()=>this.setState({showModal:'clear'})}>Limpar meus dados da demonstração</Button></>}
 modal(){const m=this.state.showModal;if(!m)return null;let title='Informação',body:any=null,action:any=null;if(m.startsWith('comment:')){const id=Number(m.split(':')[1]);const post=this.state.posts.find(x=>x.id===id);title='Responder à publicação';body=<><p className="muted">{post?.body}</p><textarea value={this.state.commentsDraft[String(id)]||''} placeholder="Escreva sua resposta" rows={3} onChange={e=>this.setState(s=>({commentsDraft:{...s.commentsDraft,[id]:e.target.value}}))}/></>;action=<Button onClick={()=>{const msg=(this.state.commentsDraft[String(id)]||'').trim();if(!msg)return;this.setState(s=>({posts:s.posts.map(x=>x.id===id?{...x,comments:[...x.comments,msg]}:x),commentsDraft:{...s.commentsDraft,[id]:''},showModal:''}));this.flash('Resposta adicionada à conversa da demo.')}}>Responder</Button>}
 else if(m.startsWith('student:')){title='Acompanhamento ilustrativo';body=<p>Os dados de {m.split(':')[1]} são fictícios e servem apenas para demonstrar a interface do educador.</p>}
 else if(m.startsWith('activity:')){const a=this.state.activities[Number(m.split(':')[1])];title=a?.title||'Atividade';body=<><p>{a?.instructions}</p><p className="muted">Turma: {a?.group} · Resposta: {a?.answerType} · {a?.published?'Publicada':'Rascunho'} na demo</p></>}
 else if(m==='favorites'){title='Meus favoritos';body=this.state.bookmarks.length?<div className="stack">{this.state.bookmarks.map(x=><Tile key={x} icon="bookmark" title={x} onClick={()=>this.toggleBookmark(x)}/>)}</div>:<p>Você ainda não salvou nenhum conteúdo. Explore o vocabulário e a biblioteca.</p>}
 else if(m==='restart'||m==='clear'){title='Reiniciar demonstração?';body=<p>Isso apagará o progresso, mensagens, atividades e preferências salvos neste navegador.</p>;action=<Button onClick={()=>{localStorage.removeItem(STORE);this.setState({...initial});history.pushState({},'','#welcome');window.scrollTo(0,0)}}>Apagar dados e reiniciar</Button>}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)this.setState({showModal:''})}}><div className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><h2>{title}</h2><button className="icon-button" aria-label="Fechar" onClick={()=>this.setState({showModal:''})}><Icon name="close"/></button></div>{body}{action||<Button kind="outline" onClick={()=>this.setState({showModal:''})}>Fechar</Button>}</div></div>}
 renderPage(){switch(this.state.page){case 'welcome':return this.welcome();case 'choose':return this.choose();case 'home':return this.home();case 'tracks':return this.tracks();case 'track':return this.track();case 'lesson':return this.lesson();case 'practice':return this.practice();case 'vocabulary':return this.vocabulary();case 'progress':return this.progressPage();case 'chat':return this.chat();case 'career':return this.career();case 'training':return this.training();case 'reading':return this.reading();case 'article':return this.article();case 'learn':return this.learn();case 'inclusion':return this.inclusion();case 'community':return this.community();case 'teacher':return this.teacher();case 'activity':return this.activity();case 'students':return this.students();case 'library':return this.library();case 'teacherCommunity':return this.community(true);case 'profile':return this.profile();case 'settings':return this.settings();case 'notifications':return this.notifications();case 'support':return this.support();case 'privacy':return this.privacy();default:return this.welcome()}}
 render(){const onboard=this.state.page==='welcome'||this.state.page==='choose';const role=this.state.role;return <div className={'app-layout '+(onboard?'onboarding':'')}>
 {!onboard&&<aside className="sidebar"><Brand/><span className="sidebar-caption">AMBIENTE DE DEMONSTRAÇÃO</span><nav aria-label="Navegação principal">{this.navItems().map(n=><button className={n.page===this.state.page?'active':''} key={n.page} onClick={()=>this.go(n.page)}><Icon name={n.icon}/>{n.label}</button>)}<button onClick={()=>this.go(role==='educador'?'activity':'vocabulary')}><Icon name={role==='educador'?'plus':'search'}/>{role==='educador'?'Criar atividade':'Vocabulário'}</button></nav><div className="sidebar-bottom"><button onClick={()=>this.go('settings')}><Icon name="settings"/> Preferências</button><button onClick={()=>this.go('choose')}><Icon name="users"/> Trocar de perfil</button></div><span className="sidebar-foot">Sinalis • Demo interativa</span></aside>}
 <main className="main-content"><div className={'app-surface '+(onboard?'app-surface-onboard':'')}>{this.renderPage()}</div>{!onboard&&<nav className="bottom-nav" aria-label="Navegação inferior">{this.navItems().map(n=><button key={n.page} className={n.page===this.state.page?'active':''} aria-label={n.label} onClick={()=>this.go(n.page)}><Icon name={n.icon} size={22}/><span>{n.label}</span></button>)}</nav>}</main>
 {!onboard&&<div className="desktop-aside"><div className="tip-panel"><span className="demo-tag">MODO DEMO</span><img src="assets/mascote.png" alt="Mascote Sinalis"/><h3>Aprender é construir pontes.</h3><p>Explore os recursos do Sinalis sem login nem senha. Cada ação funciona como uma demonstração local.</p><Button kind="outline" onClick={()=>this.go('choose')}>Trocar jornada</Button></div><button className="aside-privacy" onClick={()=>this.go('privacy')}><Icon name="shield" size={18}/> Seus dados ficam no navegador</button></div>}
 {this.state.toast&&<div className="toast-message" role="status"><Icon name="check" size={18}/>{this.state.toast}</div>}{this.modal()}</div>}
}
ReactDOM.render(<App/>,document.getElementById('root'));
